def calculate_tax(amount: float) -> float:
    return round(amount * 0.08, 2)

# Main guard prevents execution on import
if __name__ == '__main__':
    sample = calculate_tax(100.0)
    print(f'Test execution under main guard: {sample}')

# Solution to circular dependency: extract shared models or use local import
def get_service_metrics():
    # Local import inside function boundary defers resolution
    import time
    return {'timestamp': int(time.time()), 'status': 'healthy'}

print('Deferred boundary check:', get_service_metrics()['status'])
